const health = $('Read TruthLens health').first().json || {};
const benchmark = $json || {};
const alerts = [];
if (health.error || !health.status) alerts.push('BACKEND_UNAVAILABLE_OR_MALFORMED');
else if (health.status !== 'ok') alerts.push('BACKEND_DEGRADED');
if (health.model_readiness && /fallback|degraded|unavailable/i.test(health.model_readiness)) alerts.push('MODEL_READINESS_DEGRADED');
if (health.vector_store_readiness && /empty|fallback|degraded|unavailable/i.test(health.vector_store_readiness)) alerts.push('VECTOR_STORE_DEGRADED');
if (benchmark.error || !Array.isArray(benchmark.artifacts)) alerts.push('BENCHMARK_RESPONSE_MALFORMED');
const artifacts = Array.isArray(benchmark.artifacts) ? benchmark.artifacts : [];
const names = new Set(artifacts.map(item => item.name));
for (const required of ['baseline_verifier.json', 'experiment2_verifier_comparison.json', 'rag_validation.json']) if (!names.has(required)) alerts.push(`MISSING_ARTIFACT:${required}`);
const current = artifacts.find(item => item.name === 'experiment2_verifier_comparison.json');
const currentData = current?.data || {};
const baseline = currentData.models?.baseline?.metrics || currentData.baseline?.metrics || currentData.baseline || {};
const observedBaselineMacroF1 = baseline.macro_f1 === undefined ? null : Number(baseline.macro_f1);
const defaultReferenceBaselineMacroF1 = 0.6758189800742992;
const configuredReference = Number($env.TRUTHLENS_MIN_BASELINE_MACRO_F1);
const referenceBaselineMacroF1 = Number.isFinite(configuredReference) ? configuredReference : defaultReferenceBaselineMacroF1;
const comparisonEpsilon = 1e-9;
const macroF1Regression = Number.isFinite(observedBaselineMacroF1) && observedBaselineMacroF1 < referenceBaselineMacroF1 - comparisonEpsilon;
if (macroF1Regression) alerts.push('QUALITY_REGRESSION_MACRO_F1');
return [{json: {ok: alerts.length === 0, checked_at: new Date().toISOString(), alerts: [...new Set(alerts)], health, benchmark_status: benchmark.status || 'unavailable', available_artifacts: artifacts.map(item => item.name), observed_baseline_macro_f1: observedBaselineMacroF1, reference_baseline_macro_f1: referenceBaselineMacroF1, comparison_epsilon: comparisonEpsilon, macro_f1_regression: macroF1Regression, latency_signal: null, provider_signal: health.model_readiness || null, limitations: ['Latency regression is unavailable unless a comparable artifact is exposed.', 'This workflow does not invent live quality or latency metrics.']}}];
